var ENT=[["Discoverer", "Signature Discoverer pillar of the Build Performance Optimizer framework."], ["Validator", "Signature Validator pillar of the Build Performance Optimizer framework."], ["Composer", "Signature Composer pillar of the Build Performance Optimizer framework."], ["Exchanger", "Signature Exchanger pillar of the Build Performance Optimizer framework."], ["Checkpointer", "Signature Checkpointer pillar of the Build Performance Optimizer framework."], ["Reviewer", "Signature Reviewer pillar of the Build Performance Optimizer framework."], ["Gapfinder", "Signature Gapfinder pillar of the Build Performance Optimizer framework."]];
